import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.products().listProducts(Map.of("limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("products")) {
    Map<?, ?> product = (Map<?, ?>) row;
    System.out.println(product.get("id") + " " + product.get("name") + " " + product.get("sku"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

