update_product.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;
import static java.util.Map.entry;

ApiResponse response = client.products().updateProduct(101, Map.ofEntries(
        entry("name", "Cotton T-Shirt"), entry("sku", "TSHIRT-001"), entry("base_price", 25.0),
        entry("product_type", "physical"), entry("available", true), entry("is_on_sale", false),
        entry("available_on_date_range", false),
        entry("available_on_weekdays", Map.of("enabled", false, "weekdays", List.of())),
        entry("available_for", "all"),
        entry("selected_customers", Map.of("customers", List.of(), "groups", List.of())),
        entry("invoice_note", "Ships in 2 business days"),
        entry("advanced", Map.of("advance_information", Map.of("mpn", "MPN-0001")))));
Map<?, ?> product = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("product");
Map<?, ?> advanced = (Map<?, ?>) product.get("advanced");
System.out.println(product.get("invoice_note") + " " + product.get("version"));
System.out.println(((Map<?, ?>) advanced.get("advance_information")).get("mpn"));

